package com.hotstacks;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class HotStacksPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(HotStacksPlugin.class);
		RuneLite.main(args);
	}
}

package com.hotstacks;

/** The animated effect drawn on the most valuable stacks in view. */
public enum TopEffect
{
	/** No effect. */
	NONE("None"),
	/** Glowing embers rising from the bottom of the slot, as if from a fire beneath it. */
	EMBERS("Embers"),
	/** Glowing embers spitting outward from the centre, as if the item were a hot coal. */
	RADIAL_EMBERS("Radial embers"),
	/** Twinkling four-point stars around the slot. */
	SPARKLE("Sparkle");

	private final String label;

	TopEffect(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.hotstacks;

/**
 * How a stack's rank (cheapest → dearest in the current view) is turned into a colour.
 * All modes position items by rank, so the palette is always fully used no matter how the
 * raw values cluster; they differ only in the palette itself.
 */
public enum ColourMode
{
	/** Continuous multi-stop spectrum (blue → green → yellow → orange → red). */
	HEAT_RAMP("Heat ramp (spectrum)"),
	/** Blend between the two configured colours. */
	GRADIENT("Two-colour gradient"),
	/** Every value drawn plain white, regardless of worth. */
	SINGLE("Single colour (white)"),
	/** Continuous density field over the whole bank, ramped between the two configured colours. */
	DENSITY_FIELD("Density field");

	private final String label;

	ColourMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.hotstacks;

import java.util.Arrays;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.BankTagsService;

/**
 * Works out what value (if any) a bank slot should display, and holds the sorted set of values in
 * the current view so the overlay can colour each item by its rank (cheapest → dearest).
 *
 * <p>The value set is taken from the bank item container itself, counting only the slots the game
 * hasn't hidden ({@code !isSelfHidden()}). That gives the whole bank when all tabs are shown, just
 * the open tab when one is selected, and the matches while a bank search is active — and it is
 * unaffected by scrolling, since scrolled-off slots are clipped, not hidden. This mirrors how
 * RuneLite's own bank plugin totals the currently-shown bank value.</p>
 *
 * <p>{@link #recompute()} runs on the client thread (game tick / varbit change); the overlay reads
 * the published {@code sorted} array while rendering. That array is {@code volatile} so the render
 * pass always sees a complete snapshot.</p>
 */
@Singleton
class BankValueModel
{
	private static final long[] EMPTY = new long[0];

	private final Client client;
	private final ItemManager itemManager;
	private final HotStacksConfig config;
	private final PluginManager pluginManager;
	private final WithdrawalTracker withdrawals;

	/** Sorted (ascending) shown values in the current view; what each item's rank is measured against. */
	private volatile long[] sorted = EMPTY;
	/** Total value of the current view (open tab / search / whole bank) — what effects scale against. */
	private volatile long viewTotal;
	/** The (value, itemId) pair an item must meet or beat to count as "top" this frame — see {@link
	 *  #isTop}. Computed once per rebuild from the configured top percent, rather than per item, so a
	 *  large tie at the richest value doesn't all clear the bar together. */
	private volatile long topThresholdValue = Long.MAX_VALUE;
	private volatile int topThresholdId = Integer.MAX_VALUE;
	/** Signature of the shown (itemId, quantity) slots the current {@link #sorted} was built from —
	 *  purely a reflection of the bank's own displayed contents, never nudged by {@link #invalidate()}.
	 *  This is what gates {@link WithdrawalTracker#commitPending()}, so a fresh withdrawal count only
	 *  becomes visible in lockstep with the bank slot actually losing the item. */
	private long contentSignature;
	/** Set by {@link #invalidate()}; forces the next {@link #syncToView()} to rebuild regardless of
	 *  whether the content signature changed (e.g. once a tick, to pick up price drift). */
	private volatile boolean forceRebuild = true;
	/** Whether a Bank Tag Layout is active this frame; recomputed in {@link #syncToView()}. */
	private volatile boolean layoutActive;
	/** The banktags plugin, resolved lazily as a {@link BankTagsService}; null if that plugin is absent. */
	private BankTagsService bankTags;

	@Inject
	BankValueModel(Client client, ItemManager itemManager, HotStacksConfig config, PluginManager pluginManager,
		WithdrawalTracker withdrawals)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.config = config;
		this.pluginManager = pluginManager;
		this.withdrawals = withdrawals;
	}

	/**
	 * Whether a Bank Tag Layout (a "loadout") is currently applied to the bank. Such views are a
	 * hand-arranged subset — they can contain duplicated items and dimmed "ghost" placeholders for
	 * things you don't own (see {@code LayoutManager}), so their values don't reflect real holdings.
	 * The whole overlay stands down while one is active. Read from the flag cached each frame by
	 * {@link #syncToView()}, so per-item render calls don't each re-query.
	 */
	boolean layoutActive()
	{
		return layoutActive;
	}

	/**
	 * The banktags plugin exposed as a {@link BankTagsService}. It lives in its own plugin injector,
	 * so it can't be {@code @Inject}ed here; instead it's found by identity through the
	 * {@link PluginManager} (banktags implements the service) and cached once resolved.
	 */
	private BankTagsService bankTags()
	{
		if (bankTags == null)
		{
			for (Plugin p : pluginManager.getPlugins())
			{
				if (p instanceof BankTagsService)
				{
					bankTags = (BankTagsService) p;
					break;
				}
			}
		}
		return bankTags;
	}

	/**
	 * The weight to show/rank a bank slot by, or {@code 0} for none, in the current
	 * {@link ValueSource}:
	 * <ul>
	 *   <li><b>GE</b> — {@link ItemManager#getItemPrice(int)}, the same source as RuneLite's
	 *   built-in Item Prices, which resolves combination items (charged tridents, avernic defender,
	 *   echo boots, …) to their tradeable parts.</li>
	 *   <li><b>High alch</b> — the item's high-alchemy value.</li>
	 *   <li><b>High alch profit</b> — high-alch value minus the current nature-rune price; a
	 *   non-positive result yields 0 (no value).</li>
	 *   <li><b>Withdraws</b> — how many times you've withdrawn the item, ever, on this account.
	 *   Quantity-independent: withdrawing 28 of an item counts the same as withdrawing 1.</li>
	 * </ul>
	 */
	long weightOf(int itemId, int quantity)
	{
		// Bank Tag Layouts marks an item placed in a layout but not actually owned (a "layout
		// placeholder", dimmed and non-interactable) with a sentinel quantity of Integer.MAX_VALUE
		// (see LayoutManager). Those ghosts carry no weight, so exclude them like an empty slot —
		// otherwise unit × MAX_VALUE ranks them as the richest stack in the bank.
		if (quantity <= 0 || quantity == Integer.MAX_VALUE)
		{
			return 0;
		}
		if (config.valueSource() == ValueSource.WITHDRAWS)
		{
			return withdrawals.count(itemId);
		}
		long unit = unitValue(itemId);
		return unit <= 0 ? 0 : unit * quantity;
	}

	private long unitValue(int itemId)
	{
		switch (config.valueSource())
		{
			case HIGH_ALCH:
				return itemManager.getItemComposition(itemId).getHaPrice();
			case HIGH_ALCH_PROFIT:
				return (long) itemManager.getItemComposition(itemId).getHaPrice() - itemManager.getItemPrice(ItemID.NATURERUNE);
			case GE:
			default:
				return itemManager.getItemPrice(itemId);
		}
	}

	/** Total value of the current view (tab / search / whole bank); what {@code Scale effect by value} uses. */
	long viewTotal()
	{
		return viewTotal;
	}

	/** Forces {@link #syncToView()} to rebuild on its next call (e.g. once a tick, to pick up price
	 *  changes even when the shown items are unchanged). Does not by itself reveal a newly recorded
	 *  withdrawal — see {@link WithdrawalTracker}. */
	void invalidate()
	{
		forceRebuild = true;
	}

	/**
	 * Brings the ranking set in step with the bank slots currently shown. Meant to run every frame
	 * on {@code BeforeRender}, just before the overlay draws, so the ranking reflects exactly the
	 * same widget state the render sees — that is what prevents the one-frame flash when the shown
	 * set changes (e.g. opening the whole bank from a tab), where the overlay would otherwise rank
	 * every item against the previous, smaller set.
	 *
	 * <p>A cheap signature over the shown slots is computed first; the expensive pricing/sort pass
	 * only runs when that signature changes (or after {@link #invalidate()}), so the common
	 * unchanged frame is just one light scan.</p>
	 */
	void syncToView()
	{
		Widget container = client.getWidget(ComponentID.BANK_ITEM_CONTAINER);
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		Widget[] children = container == null ? null : container.getChildren();
		if (children == null || bank == null)
		{
			sorted = EMPTY;
			viewTotal = 0;
			contentSignature = 0;
			layoutActive = false;
			return;
		}

		// A loadout (Bank Tag Layout) is a curated arrangement with fake quantities and possible
		// duplicates, so its values would be misleading — stand the whole overlay down while one is
		// shown. Reset the content signature so the real bank is re-ranked once it closes.
		BankTagsService tags = bankTags();
		if (tags != null && tags.getActiveLayout() != null)
		{
			sorted = EMPTY;
			viewTotal = 0;
			contentSignature = -1;
			layoutActive = true;
			return;
		}
		layoutActive = false;

		// The bank item widgets are the first bank.size() children; later children are tabs etc.
		int slots = Math.min(bank.size(), children.length);

		// Cheap pass: signature of the shown (id, quantity) slots — no pricing. This reflects only
		// the bank's own displayed contents, so it's what gates committing a pending withdrawal
		// count into visibility (see WithdrawalTracker) — a forced rebuild alone must not do that,
		// or a slot would rank by its just-clicked count before the game has actually removed the item.
		long sig = 1469598103934665603L;
		for (int i = 0; i < slots; i++)
		{
			Widget child = children[i];
			if (child == null || child.isSelfHidden() || child.getItemId() <= 0)
			{
				continue;
			}
			sig = (sig ^ child.getItemId()) * 1099511628211L;
			sig = (sig ^ child.getItemQuantity()) * 1099511628211L;
		}
		boolean contentChanged = sig != contentSignature;
		if (!contentChanged && !forceRebuild)
		{
			return;
		}
		contentSignature = sig;
		forceRebuild = false;

		if (contentChanged)
		{
			withdrawals.commitPending();
		}

		// The view changed: price the shown slots and rebuild the ranking set.
		long[] values = new long[slots];
		int[] ids = new int[slots];
		int n = 0;
		for (int i = 0; i < slots; i++)
		{
			Widget child = children[i];
			if (child == null || child.isSelfHidden() || child.getItemId() <= 0)
			{
				continue;
			}
			long value = weightOf(child.getItemId(), child.getItemQuantity());
			if (value > 0)
			{
				values[n] = value;
				ids[n] = child.getItemId();
				n++;
			}
		}

		long total = 0;
		for (int i = 0; i < n; i++)
		{
			total += values[i];
		}
		viewTotal = total;

		long[] s = Arrays.copyOf(values, n);
		Arrays.sort(s);
		sorted = s;

		computeTopThreshold(values, ids, n);
	}

	/**
	 * Picks the (value, itemId) cutoff an item must meet or beat to count as {@link #isTop}. Ties at
	 * the cutoff value are broken by item id — a stable, arbitrary but deterministic order — so that
	 * however many items share the richest value, at most the configured top percent of them (never
	 * all of them) end up marked, and the same subset is picked every frame rather than flickering.
	 */
	private void computeTopThreshold(long[] values, int[] ids, int n)
	{
		double topPercent = config.sparkleTopPercent();
		if (n <= 1 || topPercent <= 0)
		{
			topThresholdValue = Long.MAX_VALUE;
			topThresholdId = Integer.MAX_VALUE;
			return;
		}

		Integer[] order = new Integer[n];
		for (int i = 0; i < n; i++)
		{
			order[i] = i;
		}
		Arrays.sort(order, (a, b) ->
		{
			int c = Long.compare(values[a], values[b]);
			return c != 0 ? c : Integer.compare(ids[a], ids[b]);
		});

		int topCount = Math.min(n, Math.max(1, (int) Math.round(n * topPercent / 100.0)));
		int cutoff = order[n - topCount];
		topThresholdValue = values[cutoff];
		topThresholdId = ids[cutoff];
	}

	/**
	 * Where {@code value} sits in the current view from 0 (cheapest shown stack) to 1 (dearest).
	 * Ranking, rather than raw magnitude, guarantees the palette is spread evenly across the items
	 * however their values cluster. Returns 1 when there is nothing to rank against.
	 *
	 * <p>Ties resolve to the <em>top</em> of their band: {@link Arrays#binarySearch} may land on any
	 * matching index, so a run of equal values is walked forward to its last occurrence. Without
	 * this, a view where every shown value is identical (a plausible whole-bank case for {@link
	 * ValueSource#WITHDRAWS}, where a small integer count ties far more often than a gp value would)
	 * could have every item hash to rank 0 instead of the 1 they all equally deserve — silently
	 * flattening every blob in the density field to zero height.</p>
	 */
	double rankFraction(long value)
	{
		long[] s = sorted;
		int n = s.length;
		if (n <= 1)
		{
			return 1.0;
		}
		int idx = Arrays.binarySearch(s, value);
		if (idx < 0)
		{
			idx = -idx - 1;
		}
		else
		{
			while (idx + 1 < n && s[idx + 1] == value)
			{
				idx++;
			}
		}
		if (idx >= n)
		{
			idx = n - 1;
		}
		return (double) idx / (n - 1);
	}

	/**
	 * Whether ({@code value}, {@code itemId}) meets or beats the current top-percent cutoff computed
	 * in {@link #computeTopThreshold}. Comparing the pair (not just the value) is what keeps a large
	 * tie at the richest value from all qualifying together — see that method's javadoc.
	 */
	boolean isTop(long value, int itemId)
	{
		if (sorted.length <= 1)
		{
			return false;
		}
		if (value != topThresholdValue)
		{
			return value > topThresholdValue;
		}
		return itemId >= topThresholdId;
	}
}

package com.hotstacks;

/**
 * Which number drives the whole plugin — the value label, the heat-map ranking, the thermal tint
 * and the effects alike. Must be {@code public}: config methods return this via a JDK proxy in
 * another module, and a package-private enum there throws {@code IllegalAccessError} at render.
 */
public enum ValueSource
{
	/** Grand Exchange / wiki price (via RuneLite's item price mapping). */
	GE("GE value"),
	/** High alchemy value. */
	HIGH_ALCH("High alch value"),
	/** High alchemy value minus the current nature-rune price. */
	HIGH_ALCH_PROFIT("High alch profit"),
	/** How many times you've withdrawn the item from the bank, this account, ever. */
	WITHDRAWS("Withdraws");

	private final String label;

	ValueSource(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.hotstacks;

import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

/**
 * Counts how many times each item has been withdrawn from the bank, for the {@link
 * ValueSource#WITHDRAWS} value source. A withdrawal is a single Withdraw-N/X/All click, counted
 * once regardless of the quantity it moved — this tracks how often you reach for an item, not how
 * much of it passes through.
 *
 * <p>Counts are lifetime and kept per game account (RuneLite's per-RSProfile config storage), so an
 * alt's habits don't bleed into another's. There is no reset; the map only grows.</p>
 *
 * <p>A click and the bank actually losing the item are two different moments — the server takes a
 * tick or two to process the withdrawal, but the click fires immediately. If {@link #count} picked
 * up a fresh increment straight away, the bank's forced per-tick re-rank (see {@code
 * BankValueModel#invalidate()}) would briefly rank the slot by its new count while the slot still
 * shows its pre-withdrawal quantity — a one-tick flash. So a new count is held in {@link #pending}
 * (and persisted right away, so a click is never lost) and only becomes visible to {@link #count}
 * once {@link #commitPending()} is called — which {@code BankValueModel} does exactly when the
 * bank's own displayed contents have actually changed, keeping the two in lockstep.</p>
 */
@Singleton
class WithdrawalTracker
{
	private static final String KEY = "withdrawals";
	private static final Type MAP_TYPE = new TypeToken<Map<Integer, Integer>>()
	{
	}.getType();

	private final ConfigManager configManager;
	private final ItemManager itemManager;

	/** The persisted, up-to-date total — updated (and saved) the instant a withdrawal is recorded. */
	private Map<Integer, Integer> counts = new HashMap<>();
	/** What {@link #count} reads; only caught up to {@link #counts} by {@link #commitPending()}. */
	private Map<Integer, Integer> visible = new HashMap<>();
	private boolean dirty;

	@Inject
	WithdrawalTracker(ConfigManager configManager, ItemManager itemManager)
	{
		this.configManager = configManager;
		this.itemManager = itemManager;
	}

	/** Loads this account's counts, replacing whatever was held for the previous one. */
	void load()
	{
		Map<Integer, Integer> stored = configManager.getRSProfileConfiguration(HotStacksConfig.GROUP, KEY, MAP_TYPE);
		counts = stored == null ? new HashMap<>() : new HashMap<>(stored);
		visible = new HashMap<>(counts);
		dirty = false;
	}

	/** Records one withdrawal of {@code itemId} and persists immediately; not yet visible to {@link #count}. */
	void record(int itemId)
	{
		int id = itemManager.canonicalize(itemId);
		counts.merge(id, 1, Integer::sum);
		dirty = true;
		configManager.setRSProfileConfiguration(HotStacksConfig.GROUP, KEY, counts);
	}

	/** Makes any counts recorded since the last commit visible to {@link #count}. */
	void commitPending()
	{
		if (dirty)
		{
			visible = new HashMap<>(counts);
			dirty = false;
		}
	}

	/** How many times {@code itemId} (or its noted/placeholder variant) has been withdrawn. */
	int count(int itemId)
	{
		Integer c = visible.get(itemManager.canonicalize(itemId));
		return c == null ? 0 : c;
	}
}

package com.hotstacks;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Hot Stacks",
	description = "Shows each bank stack's value on it as a heat map; colours rank against the whole bank, or the open tab",
	tags = {"bank", "value", "wealth", "heatmap", "heat", "density map", "density", "embers", "price", "gp", "stacks", "worth", "withdraws"}
)
public class HotStacksPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private HotStacksOverlay overlay;
	@Inject
	private HeatFieldOverlay heatFieldOverlay;
	@Inject
	private BankValueModel model;
	@Inject
	private WithdrawalTracker withdrawalTracker;

	@Provides
	HotStacksConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(HotStacksConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(heatFieldOverlay);
		overlayManager.add(overlay);
		withdrawalTracker.load();
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(heatFieldOverlay);
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		// Re-rank against the slots shown this frame, right before the overlay draws. Keeping this
		// in lockstep with rendering is what avoids the one-frame flash when the shown set changes.
		model.syncToView();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// Force a rebuild each tick so price changes are picked up even when the shown items don't
		// change; syncToView() does the actual work on the next frame.
		model.invalidate();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// Changing the value source (or any setting) alters the values without changing the shown
		// items, so force a rebuild rather than waiting for the signature to change.
		if (HotStacksConfig.GROUP.equals(event.getGroup()))
		{
			model.invalidate();
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		// A withdraw click on a bank slot — guarded by interface so GE collects, deposit boxes and
		// non-bank "Withdraw" options elsewhere don't get counted. Text-matched rather than by
		// MenuAction since withdraw quantity/mode variants (1/5/10/X/All) share no single action id.
		if (!event.getMenuOption().startsWith("Withdraw"))
		{
			return;
		}
		int group = WidgetUtil.componentToInterface(event.getWidgetId());
		if (group != InterfaceID.BANKMAIN && group != InterfaceID.SHARED_BANK)
		{
			return;
		}
		// Recorded immediately (so a click is never lost), but not yet visible to ranking — the model
		// only reveals it once the bank's own contents actually reflect the withdrawal, avoiding a
		// one-tick flash where a slot ranks by its new count while still showing its old quantity.
		withdrawalTracker.record(event.getItemId());
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		// Withdrawal counts are per-account; reload so an alt's habits don't bleed into another's.
		withdrawalTracker.load();
	}
}

package com.hotstacks;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Point;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.QuantityFormatter;

/**
 * Draws each bank stack's value on its slot, coloured by the stack's rank among everything in
 * view (cheapest → dearest), an optional thermal tint of the whole slot, and an animated effect on
 * the most valuable stacks. {@code renderItemOverlay} is invoked once per visible bank item each
 * frame.
 */
@Singleton
class HotStacksOverlay extends WidgetItemOverlay
{
	/** Share of total bank wealth at which value-scaling reaches full intensity. */
	private static final double WEALTH_REF = 0.06;
	/** Intensity multiplier range for value-scaling (effect and heat map tint). */
	private static final double INTENSITY_FLOOR = 0.3;
	private static final double INTENSITY_CEIL = 1.35;
	/** Base alpha of the heat map tint at its fixed 40% strength. */
	private static final int TINT_BASE_ALPHA = 84;

	private final BankValueModel model;
	private final HotStacksConfig config;

	@Inject
	HotStacksOverlay(BankValueModel model, HotStacksConfig config)
	{
		this.model = model;
		this.config = config;
		showOnBank();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (model.layoutActive())
		{
			// A loadout (Bank Tag Layout) is showing — its curated, fake-quantity items would skew
			// the values, so draw nothing over it.
			return;
		}

		long value = model.weightOf(itemId, widgetItem.getQuantity());
		if (value <= 0)
		{
			// No weight in the current source (untradeable in GE mode, un-alchable, ≤0 profit, never
			// withdrawn, …).
			return;
		}

		// Everything keys off the one weight. The label is shown when the "Stack value" toggle is on
		// and (for the money sources) the stack clears the clutter threshold; a withdraw count of any
		// size is shown as-is, since there's no gp-scale threshold that means anything for it. The
		// tint and effect run regardless of the label.
		boolean isWithdraws = config.valueSource() == ValueSource.WITHDRAWS;
		boolean showValue = config.showStackValue() && (isWithdraws || value >= config.minValue());
		// The per-slot tint handles every colour mode except Density field, which is drawn as one
		// whole-bank pass by HeatFieldOverlay instead.
		boolean tint = config.thermalTint() && config.colourMode() != ColourMode.DENSITY_FIELD;
		TopEffect effect = model.isTop(value, itemId) ? config.topEffect() : TopEffect.NONE;
		if (!showValue && !tint && effect == TopEffect.NONE)
		{
			return;
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		if (bounds == null)
		{
			return;
		}

		double rank = model.rankFraction(value);
		Color color = colourFor(rank);

		// 1. Heat map tint sits under everything. Scaled by rank so the whole view gets a gradient
		//    of blooms (wealth-fraction would collapse all but the top few to nothing here).
		if (tint)
		{
			double tintIntensity = config.scaleHeatmapByValue() ? intensityFor(rank) : 1.0;
			drawTint(graphics, bounds, color, tintIntensity);
		}

		// 2. Value label.
		if (showValue)
		{
			String text = isWithdraws ? Long.toString(value) : QuantityFormatter.quantityToStackSize(value);
			graphics.setFont(fontFor(rank));
			FontMetrics metrics = graphics.getFontMetrics();
			int x = bounds.x + (bounds.width - metrics.stringWidth(text)) / 2;
			int y = bounds.y + bounds.height - metrics.getDescent();

			if (config.coverText())
			{
				// Overwrite anything else drawn at the bottom of the slot (item charges, etc.).
				int top = y - metrics.getAscent();
				graphics.setColor(config.textBackgroundColor());
				graphics.fillRect(bounds.x, top, bounds.width, metrics.getAscent() + metrics.getDescent());
			}

			OverlayUtil.renderTextLocation(graphics, new Point(x, y), text, color);
		}

		// 3. Effect sits on top so it drifts around/in front of the item. Scaled by the stack's
		//    share of whole-bank wealth (it only marks the top few, where fractions vary enough).
		double intensity = config.scaleEffectByValue() ? intensityFor(wealthNorm(value)) : 1.0;
		if (effect == TopEffect.EMBERS)
		{
			drawEmbers(graphics, bounds, false, intensity);
		}
		else if (effect == TopEffect.RADIAL_EMBERS)
		{
			drawEmbers(graphics, bounds, true, intensity);
		}
		else if (effect == TopEffect.SPARKLE)
		{
			drawSparkles(graphics, bounds, intensity);
		}
	}

	/** Maps a normalised position [0, 1] to an intensity multiplier [floor, ceil]. */
	private double intensityFor(double norm)
	{
		double n = norm < 0 ? 0 : Math.min(1.0, norm);
		return INTENSITY_FLOOR + (INTENSITY_CEIL - INTENSITY_FLOOR) * n;
	}

	/** A stack's share of the current view's total value, normalised so {@link #WEALTH_REF} maps to full. */
	private double wealthNorm(long value)
	{
		long total = model.viewTotal();
		double frac = total > 0 ? (double) value / total : 0;
		return Math.min(1.0, frac / WEALTH_REF);
	}

	/**
	 * Soft radial wash of the slot in its heat colour. {@code intensity} scales both its alpha and
	 * its radius, so a value-scaled heat map shows bigger, stronger blooms on your dearest stacks.
	 */
	private void drawTint(Graphics2D graphics, Rectangle bounds, Color color, double intensity)
	{
		int alpha = clampAlpha((int) (TINT_BASE_ALPHA * intensity));
		double radius = Math.max(bounds.width, bounds.height) * 0.62 * intensity;
		if (alpha <= 0 || radius < 1)
		{
			return;
		}
		Color hot = new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
		Color edge = new Color(color.getRed(), color.getGreen(), color.getBlue(), 0);
		double cx = bounds.x + bounds.width / 2.0;
		double cy = bounds.y + bounds.height / 2.0;
		graphics.setPaint(new RadialGradientPaint(
			new java.awt.geom.Point2D.Double(cx, cy),
			(float) radius,
			new float[]{0f, 1f},
			new Color[]{hot, edge}));
		graphics.fill(new java.awt.geom.Ellipse2D.Double(cx - radius, cy - radius, radius * 2, radius * 2));
	}

	private Color colourFor(double rank)
	{
		switch (config.colourMode())
		{
			case SINGLE:
				return Color.WHITE;
			case GRADIENT:
			case DENSITY_FIELD:   // label follows the configured ramp; the field itself is drawn separately
				return HeatColor.blend(rank, config.lowColor(), config.highColor());
			case HEAT_RAMP:
			default:
				return HeatColor.ramp(rank);
		}
	}

	private Font fontFor(double rank)
	{
		if (!config.scaleFontByValue())
		{
			return FontManager.getRunescapeSmallFont();
		}
		if (rank >= 0.9)
		{
			return FontManager.getRunescapeBoldFont();
		}
		if (rank >= 0.6)
		{
			return FontManager.getRunescapeFont();
		}
		return FontManager.getRunescapeSmallFont();
	}

	/** A sparkle: relative position within the slot (0..1), animation phase, and max radius. */
	private static final double[][] SPARKLES = {
		// {fx, fy, phase, maxRadius}
		{0.84, 0.15, 0.0, 7.5},
		{0.16, 0.24, 2.1, 6.0},
		{0.68, 0.78, 4.2, 5.0},
		{0.34, 0.62, 5.5, 4.5},
	};

	/**
	 * A few four-point stars around the most valuable stacks, each twinkling on and off out of
	 * phase with the others. Each star is a bright core, a soft body, and long thin cross-flares
	 * for the classic sparkle glint. Animated off wall-clock time so it plays every frame.
	 */
	private void drawSparkles(Graphics2D graphics, Rectangle bounds, double intensity)
	{
		Object aa = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		double scale = effectScale();
		// Time is NOT scaled by intensity so a changing intensity never jumps the animation.
		double time = System.currentTimeMillis() / 240.0;
		for (double[] s : SPARKLES)
		{
			// max(0, sin) so each star fully vanishes for part of its cycle — a twinkle, not a pulse.
			double twinkle = Math.sin(time + s[2]);
			if (twinkle <= 0.03)
			{
				continue;
			}
			double cx = bounds.x + s[0] * bounds.width;
			double cy = bounds.y + s[1] * bounds.height;
			drawStar(graphics, cx, cy, s[3] * scale * intensity * (0.45 + 0.55 * twinkle), twinkle, intensity);
		}

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
			aa == null ? RenderingHints.VALUE_ANTIALIAS_DEFAULT : aa);
	}

	private void drawStar(Graphics2D graphics, double cx, double cy, double outer, double twinkle, double intensity)
	{
		int alpha = clampAlpha((int) (255 * twinkle * intensity));   // dearer stacks glint brighter
		// Long thin cross-flares (the glint), then the fuller star body, then a bright core.
		fillStar(graphics, cx, cy, outer * 2.0, outer * 0.08, new Color(255, 255, 255, clampAlpha((int) (200 * twinkle * intensity))));
		fillStar(graphics, cx, cy, outer, outer * 0.36, new Color(255, 250, 205, alpha));
		double core = Math.max(1.0, outer * 0.28);
		graphics.setColor(new Color(255, 255, 255, alpha));
		graphics.fill(new java.awt.geom.Ellipse2D.Double(cx - core, cy - core, core * 2, core * 2));
	}

	private void fillStar(Graphics2D graphics, double cx, double cy, double outer, double inner, Color color)
	{
		Path2D star = new Path2D.Double();
		for (int i = 0; i < 8; i++)
		{
			double angle = Math.PI / 2 + i * Math.PI / 4;
			double radius = (i % 2 == 0) ? outer : inner;
			double px = cx + Math.cos(angle) * radius;
			double py = cy - Math.sin(angle) * radius;
			if (i == 0)
			{
				star.moveTo(px, py);
			}
			else
			{
				star.lineTo(px, py);
			}
		}
		star.closePath();
		graphics.setColor(color);
		graphics.fill(star);
	}

	private static int clampAlpha(int a)
	{
		return a < 0 ? 0 : Math.min(255, a);
	}

	private static final int EMBER_COUNT = 6;
	/** Golden-ratio step spreads each ember's cycle offset evenly without any clumping. */
	private static final double GOLDEN = 0.6180339887;

	/**
	 * Glowing embers marking the most valuable stacks — a nod to the "Hot Stacks" name. Each ember
	 * runs a continuous, looping life cycle, cools from yellow to red, and fades as it travels.
	 * When {@code radial} they spit outward from the centre (as if the item were a hot coal);
	 * otherwise they rise from the bottom (as if from a fire beneath it).
	 *
	 * <p>Positions are a pure function of time and a per-slot seed (no stored state), so it animates
	 * smoothly and each item differs. Every cycle is a fresh trajectory — angle/distance/drift (or
	 * spawn/sway/height) are hashed from the ember's current cycle number, so an ember never
	 * retraces the same path twice while staying deterministic and stateless.</p>
	 */
	private void drawEmbers(Graphics2D graphics, Rectangle bounds, boolean radial, double intensity)
	{
		Object aa = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		double scale = effectScale();
		// Time is NOT scaled by intensity: a changing intensity (on a recompute) must not jump the
		// phase and restart the animation. Intensity shows through brightness and size instead.
		double t = System.currentTimeMillis() / 1000.0;
		double sizeMul = (0.7 + scale) * intensity;
		double seed = bounds.x * 0.137 + bounds.y * 0.071;
		double maxDist = Math.max(bounds.width, bounds.height) * 0.72;
		double baseY = bounds.y + bounds.height;
		double rise = bounds.height * 1.25;

		// A faint glow in the middle of the slot backs the embers.
		double gcx = bounds.x + bounds.width / 2.0;
		double gcy = bounds.y + bounds.height / 2.0;
		double glowRadius = bounds.width * 0.32;
		int glowAlpha = clampAlpha((int) (38 * intensity));
		graphics.setPaint(new RadialGradientPaint(
			new java.awt.geom.Point2D.Double(gcx, gcy),
			(float) glowRadius,
			new float[]{0f, 1f},
			new Color[]{new Color(255, 120, 30, glowAlpha), new Color(255, 120, 30, 0)}));
		graphics.fill(new java.awt.geom.Ellipse2D.Double(gcx - glowRadius, gcy - glowRadius, glowRadius * 2, glowRadius * 2));

		for (int i = 0; i < EMBER_COUNT; i++)
		{
			double offset = frac(seed + i * GOLDEN);
			double life = 1.5 + (i % 4) * 0.35;                 // seconds per cycle, varied per ember
			double cyclePos = t / life + offset;
			double cycle = Math.floor(cyclePos);                // which cycle this is — reseeds each loop
			double p = cyclePos - cycle;                        // 0 at the start, 1 at the end of travel

			// Fresh pseudo-random traits per cycle, so no cycle repeats the previous one.
			double h1 = hash(seed + i * 12.9 + cycle * 78.2);
			double h2 = hash(seed + i * 39.3 + cycle * 11.1);
			double h3 = hash(seed + i * 63.7 + cycle * 27.6);

			double x;
			double y;
			if (radial)
			{
				double angle = h1 * Math.PI * 2.0;              // a fresh outward direction each cycle
				double dist = p * maxDist * (0.7 + 0.5 * h2);   // vary how far each spark flies
				double curve = Math.sin(p * Math.PI * (1.0 + h3)) * bounds.width * 0.06;
				x = gcx + Math.cos(angle) * dist - Math.sin(angle) * curve;
				y = gcy + Math.sin(angle) * dist + Math.cos(angle) * curve;
			}
			else
			{
				double spawnX = bounds.x + bounds.width * (0.12 + 0.76 * h1);
				double sway = Math.sin(p * (1.5 + 2.5 * h3) * Math.PI + h1 * Math.PI * 2) * bounds.width * (0.07 + 0.13 * h2);
				x = spawnX + sway;
				y = baseY - p * rise * (0.8 + 0.4 * h2);        // vary how high each rise reaches
			}

			// Quick fade-in at the start, fade out as it travels; dampened, and brighter for dearer stacks.
			double alpha = Math.min(1.0, p * 6.0) * (1.0 - p) * 0.55 * intensity;
			if (alpha <= 0.02)
			{
				continue;
			}
			double r = (0.7 + 0.9 * (1.0 - p)) * sizeMul;       // shrink slightly as it travels

			int g = clampChannel((int) (215 - 175 * p));        // yellow (hot) → red (cool)
			int b = clampChannel((int) (95 - 85 * p));
			int a = clampAlpha((int) (255 * alpha));
			fillDot(graphics, x, y, r * 1.7, new Color(255, g, b, clampAlpha((int) (a * 0.22))));
			fillDot(graphics, x, y, r, new Color(255, g, b, a));
			fillDot(graphics, x, y, r * 0.45, new Color(255, 245, 205, a));
		}

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
			aa == null ? RenderingHints.VALUE_ANTIALIAS_DEFAULT : aa);
	}

	/** Deterministic pseudo-random value in [0, 1) from any input — the classic sine hash. */
	private static double hash(double n)
	{
		return frac(Math.sin(n) * 43758.5453123);
	}

	private void fillDot(Graphics2D graphics, double cx, double cy, double radius, Color color)
	{
		graphics.setColor(color);
		graphics.fill(new java.awt.geom.Ellipse2D.Double(cx - radius, cy - radius, radius * 2, radius * 2));
	}

	/** The configured effect size, clamped to [0, 3] in case an out-of-range value was stored. */
	private double effectScale()
	{
		double s = config.sparkleScale();
		return s < 0 ? 0 : Math.min(3.0, s);
	}

	private static double frac(double v)
	{
		return v - Math.floor(v);
	}

	private static int clampChannel(int c)
	{
		return c < 0 ? 0 : Math.min(255, c);
	}
}

package com.hotstacks;

import java.awt.Color;

/**
 * Turns a rank fraction (0 = cheapest stack in view, 1 = dearest) into a colour.
 *
 * <p>Because items are positioned by rank rather than raw value, the palette is always spread
 * evenly across whatever is in view. Three palettes are offered (see {@link ColourMode}): a
 * continuous multi-stop spectrum, a small number of solid tiers cut from that spectrum, and a
 * plain two-colour blend.</p>
 */
final class HeatColor
{
	/** Cold → hot spectrum: blue, green, yellow, orange, red (evenly spaced). */
	private static final Color[] RAMP = {
		new Color(0x2E, 0x6F, 0xF2),
		new Color(0x2E, 0xCC, 0x40),
		new Color(0xFF, 0xDC, 0x00),
		new Color(0xFF, 0x85, 0x1B),
		new Color(0xFF, 0x41, 0x36),
	};

	private HeatColor()
	{
	}

	/** Continuous spectrum colour for a rank fraction in {@code [0, 1]}. */
	static Color ramp(double f)
	{
		f = clamp01(f);
		double scaled = f * (RAMP.length - 1);
		int i = (int) Math.floor(scaled);
		if (i >= RAMP.length - 1)
		{
			return RAMP[RAMP.length - 1];
		}
		return lerp(RAMP[i], RAMP[i + 1], scaled - i);
	}

	/** Blend between two configured colours (incl. alpha) for a rank fraction in {@code [0, 1]}. */
	static Color blend(double f, Color low, Color high)
	{
		return lerp(low, high, clamp01(f));
	}

	private static Color lerp(Color a, Color b, double f)
	{
		return new Color(
			lerp(a.getRed(), b.getRed(), f),
			lerp(a.getGreen(), b.getGreen(), f),
			lerp(a.getBlue(), b.getBlue(), f),
			lerp(a.getAlpha(), b.getAlpha(), f));
	}

	private static int lerp(int a, int b, double f)
	{
		return (int) Math.round(a + (b - a) * f);
	}

	private static double clamp01(double f)
	{
		if (f < 0)
		{
			return 0;
		}
		return f > 1 ? 1 : f;
	}
}

